def curve_eval(pts, x):
    """= MobCfg.eval (SkyyGear GearBase.eval): flat before the first / after the last point, straight lines between"""
    if x <= pts[0][0]:
        return pts[0][1]
    if x >= pts[-1][0]:
        return pts[-1][1]
    for i in range(1, len(pts)):
        if x <= pts[i][0]:
            l0, v0 = pts[i - 1]
            l1, v1 = pts[i]
            return v0 + (v1 - v0) * (x - l0) / (l1 - l0)
    return pts[-1][1]


