# the damage that really came off: the whole hit while the mob lives on; a killing blow only the health that was left before it (the
# health after the last recorded hit, else the full health)
M(mcr, r"""
public static double credited(double amt, double after, double min, double max, double lastHp) {
  if (!(amt > 0.0)) return 0.0;
  if (after > min) return amt;
  double before = lastHp >= 0.0 ? lastHp : max;
  double left = before - min;
  if (!(left > 0.0)) return 0.0;
  return amt < left ? amt : left;
}""")
M(mcr, r"""
public synchronized void add(String p, double c, double after, double min, long now) {
  this.last = now;
  this.lastHp = after;
  if (after <= min) this.blow = p;
  if (!(c > 0.0)) return;
  for (int i = 0; i < this.n; i++) {
    if (p.equals(this.who[i])) { this.dmg[i] = this.dmg[i] + c; return; }
  }
  if (this.n < SLOTS) { this.who[this.n] = p; this.dmg[this.n] = c; this.n = this.n + 1; return; }
  int lo = 0;
  for (int i = 1; i < this.n; i++) if (this.dmg[i] < this.dmg[lo]) lo = i;
  if (c > this.dmg[lo]) { this.who[lo] = p; this.dmg[lo] = c; }
}""")
M(mcr, "public synchronized double hp() { return this.lastHp; }")
