# Object[] { top, topDamage, total, killing blow, players } (first one wins a tie) or null
M(mcr, r"""
public synchronized Object[] snap() {
  if (this.n <= 0 && this.blow == null) return null;
  int top = -1;
  double tot = 0.0;
  for (int i = 0; i < this.n; i++) {
    tot = tot + this.dmg[i];
    if (top < 0 || this.dmg[i] > this.dmg[top]) top = i;
  }
  return new Object[] { top < 0 ? null : this.who[top], Double.valueOf(top < 0 ? 0.0 : this.dmg[top]), Double.valueOf(tot), this.blow, Integer.valueOf(this.n) };
}""")
# 0.1.10: every credited player, top damager first (a tie keeps the first hitter on top, as snap()), share = credited / total (sum 1):
# Object[] { String[] players, double[] shares } (empty arrays when nobody is credited)
M(mcr, r"""
public synchronized Object[] shares() {
  int c = this.n;
  String[] w = new String[c];
  double[] d = new double[c];
  double tot = 0.0;
  int m = 0;
  for (int i = 0; i < c; i++) {
    if (this.who[i] == null || !(this.dmg[i] > 0.0)) continue;
    String p = this.who[i];
    double x = this.dmg[i];
    int j = m;
    while (j > 0 && d[j - 1] < x) { w[j] = w[j - 1]; d[j] = d[j - 1]; j--; }
    w[j] = p;
    d[j] = x;
    m++;
    tot = tot + x;
  }
  String[] ps = new String[m];
  double[] sh = new double[m];
  for (int i = 0; i < m; i++) { ps[i] = w[i]; sh[i] = tot > 0.0 ? d[i] / tot : 0.0; }
  return new Object[] { ps, sh };
}""")
